<?php
declare(strict_types=1);
require_once __DIR__.'/task-fields.php';
final class LifeReminders {
 public function __construct(private LifeStore $store){$store->db->exec('CREATE TABLE IF NOT EXISTS life_push_subscriptions (id VARCHAR(64) PRIMARY KEY, owner_id INT NOT NULL DEFAULT 1, subscription TEXT NOT NULL, created_at VARCHAR(30) NOT NULL)');$store->db->exec('CREATE TABLE IF NOT EXISTS life_reminder_delivery (id VARCHAR(64) PRIMARY KEY, status VARCHAR(20) NOT NULL, updated_at VARCHAR(30) NOT NULL)');try{$store->db->exec('ALTER TABLE life_push_subscriptions ADD COLUMN owner_id INT NOT NULL DEFAULT 1');}catch(Throwable){}}
 public static function endpoint(mixed $value): string {if(!is_string($value)||strlen($value)>2048)throw new LifeError('Invalid push subscription.');$u=parse_url($value);$host=$u['host']??'';if(($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||isset($u['port'])||!in_array($host,['fcm.googleapis.com','updates.push.services.mozilla.com','web.push.apple.com','wns2-par02p.notify.windows.com'],true))throw new LifeError('Unsupported push service.');return $value;}
 private function subscriptionId(string $endpoint): string{return hash('sha256',$this->store->tenantId===1?$endpoint:$this->store->tenantId.':'.$endpoint);}
 public function subscribe(array $input): void {$endpoint=self::endpoint($input['endpoint']??null);$keys=$input['keys']??[];foreach(['p256dh'=>[87,88],'auth'=>[22,24]] as $key=>$lengths){$v=$keys[$key]??'';if(!is_string($v)||!in_array(strlen($v),$lengths,true)||!preg_match('/^[A-Za-z0-9_\-=]+$/',$v))throw new LifeError('Invalid push keys.');}$id=$this->subscriptionId($endpoint);$this->store->db->beginTransaction();try{$this->store->db->prepare('DELETE FROM life_push_subscriptions WHERE id=? AND owner_id=?')->execute([$id,$this->store->tenantId]);$q=$this->store->db->prepare('SELECT COUNT(*) FROM life_push_subscriptions WHERE owner_id=?');$q->execute([$this->store->tenantId]);if((int)$q->fetchColumn()>=10)throw new LifeError('Remove an old notification device first.');$this->store->db->prepare('INSERT INTO life_push_subscriptions (id,owner_id,subscription,created_at) VALUES (?,?,?,?)')->execute([$id,$this->store->tenantId,json_encode(['endpoint'=>$endpoint,'keys'=>$keys],JSON_THROW_ON_ERROR),LifeStore::now()]);$this->store->db->commit();}catch(Throwable $e){$this->store->db->rollBack();throw $e;}}
 public function unsubscribe(string $endpoint): void {$this->store->db->prepare('DELETE FROM life_push_subscriptions WHERE id=? AND owner_id=?')->execute([$this->subscriptionId(self::endpoint($endpoint)),$this->store->tenantId]);}
 public static function due(array $state,int $now): array {$out=[];$done=array_column(array_filter($state['lists'],fn($l)=>$l['archived']||$l['isDone']),'id');foreach($state['tasks'] as $t){if($t['archived']||in_array($t['listId'],$done,true))continue;$at=life_task_reminder($t);if($at===null||$at>$now||$at<$now-86400)continue;$out[]=['id'=>hash('sha256',$t['id'].'|'.$t['dueDate'].'|'.$t['dueTime'].'|'.$t['reminderMinutes']),'taskId'=>$t['id'],'title'=>$t['title'],'dueDate'=>$t['dueDate'],'dueTime'=>$t['dueTime'],'at'=>$at];}return $out;}
 public function pending(): array{return self::due($this->store->read()['state'],time());}
 public static function privateDir(): string {return dirname(__DIR__,3).'/private/life-push';}
 public static function config(): ?array {$path=self::privateDir().'/vapid.json';return is_file($path)?json_decode(file_get_contents($path),true):null;}
 public static function ready(): bool{return is_file(self::privateDir().'/vendor/autoload.php')&&self::config()!==null&&is_file(self::privateDir().'/scheduler-ready')&&time()-(int)file_get_contents(self::privateDir().'/scheduler-ready')<300;}
 public function send(): array {
 if(!self::ready())throw new LifeError('Push delivery is awaiting server setup.',503);
 require_once self::privateDir().'/vendor/autoload.php';$cfg=self::config();$push=new \Minishlink\WebPush\WebPush(['VAPID'=>['subject'=>'https://life.ayodsgn.com','publicKey'=>$cfg['publicKey'],'privateKey'=>$cfg['privateKey']]],['TTL'=>3600],10);
 $lock=fopen(self::privateDir().'/delivery.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))return ['sent'=>0,'busy'=>true];$sent=0;
 try{$q=$this->store->db->prepare('SELECT * FROM life_push_subscriptions WHERE owner_id=?');$q->execute([$this->store->tenantId]);$devices=$q->fetchAll(PDO::FETCH_ASSOC);foreach($this->pending() as $task){foreach($devices as $row){$id=hash('sha256',($this->store->tenantId===1?'':$this->store->tenantId.'|').$task['id'].'|'.$row['id']);$q=$this->store->db->prepare('SELECT status FROM life_reminder_delivery WHERE id=?');$q->execute([$id]);if($q->fetchColumn()==='sent')continue;$report=$push->sendOneNotification(\Minishlink\WebPush\Subscription::create(json_decode($row['subscription'],true)),json_encode(['title'=>'Life · Task reminder','body'=>$task['title'],'tag'=>$task['id'],'taskId'=>$task['taskId']],JSON_THROW_ON_ERROR));if($report->isSubscriptionExpired()){$this->store->db->prepare('DELETE FROM life_push_subscriptions WHERE id=? AND owner_id=?')->execute([$row['id'],$this->store->tenantId]);continue;}if($report->isSuccess()){$this->store->db->prepare('DELETE FROM life_reminder_delivery WHERE id=?')->execute([$id]);$this->store->db->prepare('INSERT INTO life_reminder_delivery VALUES (?,?,?)')->execute([$id,'sent',LifeStore::now()]);$sent++;}}}return ['sent'=>$sent];}finally{flock($lock,LOCK_UN);fclose($lock);}
 }
}
